package com.artcatalog.mobile;

import org.junit.Test;
import java.util.*;
import java.util.concurrent.*;
import java.lang.reflect.Field;
import static org.junit.Assert.*;

public class RecommendationTagRulesTest {
    @SuppressWarnings("unchecked") private Set<String> words(String field) throws Exception {Field value=Recommendations.class.getDeclaredField(field);value.setAccessible(true);return (Set<String>)value.get(null);}
    private boolean previousBroad(String tag,Set<String> words){return words.contains(tag)||tag.matches("(?:(?:very|extremely|absolutely|incredibly|ridiculously|ultra) )*(?:lowres|highres|absurdres|(?:low|high|absurd|huge|original|full) resolution)")||tag.matches("(?:(?:very|extremely|ultra|large|huge|massive|small|medium|high|low) )*(?:filesize|file size)")||tag.matches("(?:black|brown|blonde|red|blue|green|grey|gray|white|pink|purple|silver|orange|yellow|golden|multicolored) (?:hair|eyes)");}
    private boolean previousEligible(String tag,Set<String> generic){return tag.length()>=3&&!generic.contains(tag)&&!tag.matches("\\d+(?:girls?|boys?)|\\d+")&&!tag.matches("(?:.* commentary|commission|translated|translation request|tagme|artist name|signature|watermark)");}
    @Test public void boundedRulesMatchOriginalRegexesAcrossEvictionAndUnicode() throws Exception {Set<String> generic=words("GENERIC"),broad=words("BROAD");List<String> tags=new ArrayList<>(List.of("forest","watercolor","1girl","17boys","123","blue hair","extremely high resolution","massive file size","translated","artist name","neutral commentary","日本語","Ｆｏｒｅｓｔ","a\nb","a\u00a0b","x".repeat(300)));for(int i=0;i<10000;i++)tags.add("neutral detail "+i);for(int pass=0;pass<2;pass++)for(String raw:tags){String tag=Recommendations.normal(raw);assertEquals(tag,previousBroad(tag,broad),Recommendations.broad(tag));Post p=new Post();p.tags=List.of(raw);assertEquals(tag,previousEligible(tag,generic),Recommendations.workTags(p).contains(tag));}for(String name:List.of("NORMAL_CACHE","TAG_RULES")){Field field=Recommendations.class.getDeclaredField(name);field.setAccessible(true);Map<?,?> cache=(Map<?,?>)field.get(null);synchronized(cache){assertTrue(cache.size()<=8192);}}}
    @Test public void normalizedRuleEntriesRemainDeterministicAcrossThreads() throws Exception {ExecutorService pool=Executors.newFixedThreadPool(4);List<Future<?>> tasks=new ArrayList<>();try{for(int owner=0;owner<4;owner++){final int prefix=owner;tasks.add(pool.submit(()->{for(int i=0;i<2400;i++){String raw="neutral_"+prefix+"_"+i;String normal=Recommendations.normal(raw);assertEquals(raw.replace('_',' '),normal);assertFalse(Recommendations.broad(normal));Post p=new Post();p.tags=List.of(raw);assertTrue(Recommendations.workTags(p).contains(normal));}}));}for(Future<?> task:tasks)task.get();}finally{pool.shutdownNow();}}
    @Test public void perBuildStringReaderNeverCachesMutableArtworkDecisions(){Recommendations.TagReader reader=new Recommendations.TagReader();Post p=new Post();p.tags=new ArrayList<>(List.of("forest","watercolor","forest","1girl"));assertEquals(Recommendations.workTags(p),Recommendations.workTags(p,reader));p.artistTag="forest";p.artistTags=List.of("forest");p.tags.add("clouds");assertEquals(Set.of("watercolor","clouds"),Recommendations.workTags(p,reader));for(int i=0;i<20000;i++){p.tags=List.of("neutral_detail_"+i);assertEquals(Recommendations.workTags(p),Recommendations.workTags(p,reader));}p.artistTag="";p.artistTags=List.of();p.tags=List.of("forest","watercolor");assertEquals(Set.of("forest","watercolor"),Recommendations.workTags(p,reader));}
}
